from collections import Counter


def transform(grid):
    """Paint color 3 between successive same-colored markers in rows/columns."""
    if not grid or not grid[0]:
        return [row[:] for row in grid]
    counts = Counter(cell for row in grid for cell in row)
    background = counts.most_common(1)[0][0]
    marker_colors = set(counts) - {background}
    result = [row[:] for row in grid]
    height, width = len(grid), len(grid[0])

    for r in range(height):
        for color in marker_colors:
            points = [c for c, value in enumerate(grid[r]) if value == color]
            for left, right in zip(points, points[1:]):
                for c in range(left + 1, right):
                    result[r][c] = 3

    for c in range(width):
        for color in marker_colors:
            points = [r for r in range(height) if grid[r][c] == color]
            for top, bottom in zip(points, points[1:]):
                for r in range(top + 1, bottom):
                    result[r][c] = 3
    return result


if __name__ == "__main__":
    test = [
        [4,4,4,4,4,4,4,4,8,4,4,4,4,4,4,4,4,4,4,4,4,4,4,4,4],
        [4,4,4,4,4,4,4,4,4,4,4,4,8,4,8,4,4,4,4,4,4,4,4,4,4],
        [4,4,4,4,4,8,4,4,4,4,4,4,4,4,4,4,4,4,4,4,4,4,4,4,4],
        [4,4,4,4,4,4,4,4,4,4,4,4,4,4,4,8,4,4,4,4,4,4,4,4,4],
        [4,4,4,4,4,4,4,4,4,4,4,4,4,4,4,8,4,4,4,4,4,4,4,4,4],
    ]
    answer = transform(test)
    assert len(answer) == 5 and all(len(row) == 25 for row in answer)
    assert all(type(v) is int and 0 <= v <= 9 for row in answer for v in row)
    expected = [row[:] for row in test]
    expected[1][13] = 3
    assert answer == expected

    # Fixture-style check of horizontal and vertical interpolation.
    sample = [[5,7,5,5,7,5], [5,5,5,5,5,5], [7,5,5,5,5,7]]
    painted = transform(sample)
    assert painted[0] == [5,7,3,3,7,5]
    assert painted[2] == [7,3,3,3,3,7]
    print(answer)
